// server/engine.test.js
// Plain-Node tests (no framework). Run from the repo root:  node server/engine.test.js
// or via:  npm test

const assert = require("assert");
const { evaluateEligibility, evaluateAll } = require("./engine");
const { rawScholarships } = require("./data");

// data.js holds deadline_in_days; the real date is generated by the server.
// Tests only need a dummy deadline string.
const verified = rawScholarships
  .filter(function (s) { return s.verified; })
  .map(function (s) { return Object.assign({}, s, { deadline: "2026-12-31" }); });

const ananya = {
  name: "Ananya", gpa: 8.4, income: 180000, category: "OBC", gender: "Female",
  education_level: "UG", documents: ["Aadhaar", "Marksheet", "Bank Passbook"],
};
const rohan = {
  name: "Rohan", gpa: 7.2, income: 950000, category: "General", gender: "Male",
  education_level: "UG", documents: ["Aadhaar", "Marksheet", "Income Certificate", "Bank Passbook"],
};
const priya = {
  name: "Priya", gpa: 9.1, income: 90000, category: "SC", gender: "Female",
  education_level: "UG",
  documents: ["Aadhaar", "Marksheet", "Caste Certificate", "Income Certificate", "Bank Passbook"],
};

function ids(list) {
  return list.map(function (x) { return x.id; }).sort(function (a, b) { return a - b; });
}
function byId(group, id) {
  const all = group.matched.concat(group.partial, group.ineligible);
  return all.find(function (x) { return x.id === id; });
}
function check(name, fn) {
  try {
    fn();
    console.log("PASS: " + name);
  } catch (err) {
    console.error("FAIL: " + name);
    console.error("  " + err.message);
    process.exit(1);
  }
}

const aRes = evaluateAll(ananya, verified);
const rRes = evaluateAll(rohan, verified);
const pRes = evaluateAll(priya, verified);

check("Ananya grouping", function () {
  assert.deepStrictEqual(ids(aRes.matched), [4, 5, 6, 7]);
  assert.deepStrictEqual(ids(aRes.partial), [1, 2, 3]);
  assert.deepStrictEqual(ids(aRes.ineligible), [8, 9, 10]);
});

check("Rohan grouping", function () {
  assert.deepStrictEqual(ids(rRes.matched), [7]);
  assert.deepStrictEqual(ids(rRes.partial), []);
  assert.deepStrictEqual(ids(rRes.ineligible), [1, 2, 3, 4, 5, 6, 8, 9, 10]);
});

check("Ananya vs scheme 9: income exceeds by 20,000", function () {
  const item = byId(aRes, 9);
  assert.strictEqual(item.status, "INELIGIBLE");
  assert.ok(
    item.failedRules.some(function (r) {
      return r.indexOf("exceeds the \u20B91,60,000 limit by \u20B920,000") !== -1;
    }),
    "failedRules was: " + JSON.stringify(item.failedRules)
  );
});

check("Ananya vs scheme 3: missing two documents", function () {
  const item = byId(aRes, 3);
  assert.strictEqual(item.status, "PARTIAL");
  assert.deepStrictEqual(item.missingDocs, ["Caste Certificate", "Income Certificate"]);
});

check("Ananya vs scheme 1: missing income certificate", function () {
  const item = byId(aRes, 1);
  assert.strictEqual(item.status, "PARTIAL");
  assert.deepStrictEqual(item.missingDocs, ["Income Certificate"]);
  assert.ok(item.failedRules.indexOf("Missing documents: Income Certificate") !== -1);
});

check("Ananya vs scheme 10 is INELIGIBLE (wrong level, GPA short)", function () {
  const item = byId(aRes, 10);
  assert.strictEqual(item.status, "INELIGIBLE");
  assert.strictEqual(item.rationale, "Not eligible for PG Research Fellowship: Meant for PG students.");
});

check("Ananya vs scheme 8 is INELIGIBLE (category)", function () {
  const item = byId(aRes, 8);
  assert.strictEqual(item.status, "INELIGIBLE");
  assert.ok(item.failedRules.indexOf("Open only to SC category") !== -1);
});

check("Matched items score 100 and have no failures", function () {
  aRes.matched.forEach(function (item) {
    assert.strictEqual(item.score, 100);
    assert.strictEqual(item.failedRules.length, 0);
    assert.strictEqual(item.missingDocs.length, 0);
  });
});

check("Item shape matches the contract", function () {
  const item = byId(aRes, 1);
  ["status", "score", "passedRules", "failedRules", "missingDocs", "rationale", "title", "id"].forEach(
    function (k) { assert.ok(k in item, "missing field: " + k); }
  );
  assert.ok(Array.isArray(item.passedRules) && Array.isArray(item.failedRules));
  assert.strictEqual(typeof item.rationale, "string");
});

check("Priya (all documents, SC) qualifies for scheme 8 and not scheme 10", function () {
  assert.strictEqual(byId(pRes, 8).status, "MATCHED");
  assert.strictEqual(byId(pRes, 10).status, "INELIGIBLE");
});

check("Soft GPA miss (<= 0.5 below) is PARTIAL", function () {
  const sch = Object.assign({}, verified[3], { min_gpa: 7.5 }); // Tata scheme, student GPA 7.2
  const out = evaluateEligibility(rohan, Object.assign({}, sch, { max_income: 1000000 }));
  assert.strictEqual(out.status, "PARTIAL");
  assert.ok(out.rationale.indexOf("a slightly higher GPA") !== -1);
});

check("Hard GPA miss (> 0.5 below) is INELIGIBLE", function () {
  const sch = Object.assign({}, verified[3], { min_gpa: 8.0, max_income: 1000000 });
  const out = evaluateEligibility(rohan, sch); // 7.2 vs 8.0 -> 0.8 short
  assert.strictEqual(out.status, "INELIGIBLE");
});

check("Engine does not mutate its inputs", function () {
  const before = JSON.stringify([ananya, verified]);
  evaluateAll(ananya, verified);
  assert.strictEqual(JSON.stringify([ananya, verified]), before);
});

check("Missing fields do not throw", function () {
  const out = evaluateEligibility({}, { id: 99, title: "Bare scheme" });
  assert.ok(["MATCHED", "PARTIAL", "INELIGIBLE"].indexOf(out.status) !== -1);
  const all = evaluateAll(undefined, undefined);
  assert.deepStrictEqual(all, { matched: [], partial: [], ineligible: [] });
});

console.log("\nAll engine tests passed.");
